const parentEvidenceId = "ev_e199c55478af3a4d877b8f690a6e5ed8cd1b32659411ab1a4cb351d62438a720";
const app = rea.javascript.fromEvidence(parentEvidenceId);
const r = await app.modules.references({
  where: { path: "main.js", kind: "javascript-module" },
  offset: 0,
  limit: 9007199254740991
});
if (!r.ok) throw new Error(r.error.kind + ": " + r.error.details);
const page = r.value.page;
const external_specifiers = {};
for (const row of page.rows) {
  const id = row.identity;
  if (id.strategy === "artifact-local-key" &&
      id.namespace === "unresolved-semantic-module" &&
      id.key.startsWith("external:")) {
    const specifier = id.key.slice("external:".length);
    external_specifiers[specifier] = (external_specifiers[specifier] || 0) + row.retained_source_range_count;
  }
}
print({
  external_specifiers,
  module_identity_count: page.rows.length,
  external_module_count: Object.keys(external_specifiers).length,
  inventory_exhausted: page.coverage.exhausted,
  runtime_load_proven: false,
  artifact_sha256: page.artifact.sha256,
  evidence_ids: [parentEvidenceId, r.value.evidence_id],
  limitations: [
    "This is an inert static-reference inventory; it does not prove runtime loading or execution.",
    "Inventory exhaustion applies to retained javascript-module identities at main.js; source/semantic coverage remains partial."
  ]
});

